args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { dbr:Terror_in_a_Texas_Town dbr:The_Seventh_Company_Outdoors }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?deathDate .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
}
ORDER BY ?deathDate
LIMIT 1

